def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_last = history[-1][1]
    my_last = history[-1][0]

    total_opp_c = 0
    total_opp_d = 0
    total_my_d = 0
    for i in range(n):
        if history[i][1] == 'C':
            total_opp_c += 1
        else:
            total_opp_d += 1
        if history[i][0] == 'D':
            total_my_d += 1

    # Defect streak and cooperate streak at end for opponent
    opp_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'D':
        opp_d_streak += 1
        i -= 1

    opp_c_streak = 0
    i = n - 1
    while i >= 0 and history[i][1] == 'C':
        opp_c_streak += 1
        i -= 1

    # My defection streak at end
    my_d_streak = 0
    i = n - 1
    while i >= 0 and history[i][0] == 'D':
        my_d_streak += 1
        i -= 1

    opp_c_rate = total_opp_c / n

    # Pure always defect detection
    if n >= 4 and total_opp_c == 0:
        return 'D'
    # Pure always cooperate detection
    if n >= 4 and total_opp_d == 0:
        # cooperate but don't get endlessly exploited near end
        if n >= 98:
            return 'D'
        return 'C'

    # Endgame exploitation against highly cooperative opponents
    remaining = 100 - n
    if remaining <= 2:
        if opp_c_rate >= 0.6:
            return 'D'
        if opp_c_rate <= 0.3:
            return 'D'
        return 'C'

    # If opponent is defecting currently
    if opp_d_streak >= 3:
        # long defection streak: punish and continue defecting
        return 'D'

    if opp_d_streak == 2:
        # punish but be ready to forgive after one more
        return 'D'

    if opp_d_streak == 1:
        # single defection: punish once (defect), then recover
        if my_last == 'D':
            # we already punished; if opponent was previously very cooperative, forgive
            if opp_c_rate >= 0.75:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last
    if opp_c_streak >= 2:
        # stable cooperation: cooperate, but occasionally probe against naive opponents
        if opp_c_rate >= 0.95 and total_my_d == 0 and n > 30 and n < 90:
            # rare single probe to test exploitability
            if n % 29 == 0:
                return 'D'
        # Avoid continuing to defect against a cooperative opponent
        if my_d_streak >= 2:
            return 'C'
        return 'C'

    # opp_c_streak == 1: just recovered
    if my_d_streak >= 2:
        # we've been defecting; return to cooperation to rebuild
        return 'C'
    if my_d_streak == 1:
        # we defected once; opponent cooperated; return to cooperation usually
        if total_my_d <= 1:
            return 'C'
        if rng.random() < 0.75:
            return 'C'
        return 'D'
    # both cooperated last
    if opp_c_rate >= 0.5:
        return 'C'
    else:
        # opponent historically mostly defective but cooperated just now - reciprocate
        if rng.random() < 0.7:
            return 'C'
        return 'D'
